import SpriteKit

func spriteSheetFrames(imageNamed name: String, rows: Int, columns: Int, margin: CGFloat = 0, spacing: CGFloat = 0) -> [SKTexture] {
    let sheet = SKTexture(imageNamed: name)
    let size = sheet.size()
    let width = (size.width - 2 * margin - CGFloat(columns - 1) * spacing) / CGFloat(columns)
    let height = (size.height - 2 * margin - CGFloat(rows - 1) * spacing) / CGFloat(rows)

    return (0..<rows).flatMap { row in
        (0..<columns).map { column in
            let x = margin + CGFloat(column) * (width + spacing)
            let top = margin + CGFloat(row) * (height + spacing)
            let rect = CGRect(x: x / size.width, y: (size.height - top - height) / size.height, width: width / size.width, height: height / size.height)
            return SKTexture(rect: rect, in: sheet)
        }
    }
}

