import SpriteKit

final class BattleScene: SKScene {
    var onHealthChanged: ((Int) -> Void)?
    var onGameOver: (() -> Void)?
    private(set) var health = 100
    private let fill = SKSpriteNode(color: .systemGreen, size: CGSize(width: 180, height: 18))

    override func didMove(to view: SKView) {
        let bar = SKSpriteNode(color: .darkGray, size: CGSize(width: 188, height: 26))
        bar.position = CGPoint(x: size.width / 2, y: size.height - 60)
        bar.zPosition = 100
        addChild(bar)
        fill.anchorPoint = CGPoint(x: 0, y: 0.5)
        fill.position.x = -90
        bar.addChild(fill)
    }

    override func touchesBegan(_ touches: Set<UITouch>, with event: UIEvent?) {
        guard health > 0 else { return }
        health = max(0, health - 10)
        fill.run(.scaleX(to: CGFloat(health) / 100, duration: 0.18))
        fill.color = health > 30 ? .systemGreen : .systemRed
        onHealthChanged?(health)
        if health == 0 { isPaused = true; onGameOver?() }
    }
}

import SpriteKit
import SwiftUI

struct BattleGameView: View {
    @State private var health = 100
    @State private var isGameOver = false
    private let scene = BattleScene(size: CGSize(width: 390, height: 844))

    var body: some View {
        SpriteView(scene: scene)
            .ignoresSafeArea()
            .overlay(alignment: .topLeading) {
                Label(health.formatted(), systemImage: "heart.fill")
                    .padding().background(.black.opacity(0.55), in: .capsule).padding()
            }
            .overlay {
                if isGameOver {
                    VStack(spacing: 16) {
                        Text("Game Over").font(.largeTitle.bold())
                        Button("Neu starten") { restart() }.buttonStyle(.borderedProminent)
                    }
                    .padding(32).background(.ultraThinMaterial, in: .rect(cornerRadius: 24))
                    .transition(.scale.combined(with: .opacity))
                }
            }
            .onAppear {
                scene.scaleMode = .resizeFill
                scene.onHealthChanged = { health = $0 }
                scene.onGameOver = { withAnimation { isGameOver = true } }
            }
    }

    private func restart() {
        health = 100
        isGameOver = false
        scene.isPaused = false
        // scene.reset() setzt Lebenspunkte und Gegner zurück.
    }
}
